local _, WFJ = ...
WFJ.Data.add("book", {
  ["e1131a7d4313ab8e"] = { "Ma Kegan era molto desideroso di parlare d'altro, in particolare della sua giovinezza a Lordaeron prima della caduta.\n\nProva ancora molto amore per quel regno perduto, anche se ora è in rovina, e morto.\n\nIl mio crescente affetto per Kegan mi diede pazienza mentre aspettavo i risultati degli esperimenti.", "." },
  ["e1351b127394107f"] = { "Sicuri di poter tenere testa alle bande da guerra dei troll, o perfino agli schivi elfi se fosse stato necessario, i signori della guerra Arathi decisero di costruire una possente città fortezza nelle regioni meridionali di Lordaeron. La città stato, chiamata Strom, divenne la capitale della nazione degli Arathi, Arathor. Mentre Arathor prosperava, umani da ogni parte del vasto continente si mettevano in viaggio verso sud, in cerca della protezione e della sicurezza di Strom.", "." },
  ["e1b3dbd4cff12518"] = { "Le due statue avrebbero vigilato sul passo verso le terre del sud, divenute vulcaniche sulla scia della presenza ardente di Ragnaros. Servivano sia da monito per chiunque volesse attaccare i regni dei nani, sia da ricordo del prezzo che i Ferroscuro avevano pagato per i loro crimini.", "." },
  ["e1cd32df9ecacb7d"] = { "Tra i due fu stretto un patto. Kel'Thuzad avrebbe ricevuto l'immortalità e un potere immenso in cambio della sua servitù al Re dei Lich. Il primo compito di Kel'Thuzad fu usare la sua ricchezza e la sua influenza a Lordaeron per fondare il Cult of the Damned. Il culto prometteva uguaglianza e vita eterna a tutti i suoi membri, purché giurassero fedeltà a Ner'zhul, il dio del Cult of the Damned.", "." },
  ["e1eeb9417569935e"] = { "Generale Turalyon\n\nGià luogotenente di lord Anduin Lothar. Cavaliere della ⟦Silver Hand=Mano d'Argento⟧. Gran generale della Spedizione dell'⟦Alliance=Alleanza⟧ che marciò su Draenor, il mondo natale degli orchi. Presunto morto.\n\nEsarus thar no'Darador' - Per il Sangue e per l'Onore noi serviamo. \nFosti la mano destra della giustizia e della virtù, vecchio amico. Il tuo nome sarà sempre onorato nelle nostre sale.\n\n- Lord Uther the Lightbringer - Cavaliere della ⟦Silver Hand=Mano d'Argento⟧", "." },
})
